const CACHE="mono-mock-v66";const ASSETS=["./card-photo.js?v=66","./card-photo.css?v=66","./assets/fonts/card-tech-mono.ttf","./secret-visibility.js?v=66","./launch.js?v=66","./apple-touch-icon.png?v=66","./icon-192.png?v=66","./auth-gate.js?v=66","./auth.css?v=66","./cabinets.js?v=66","./assets/reference/limits-sticker-hq.png","./assets/reference/market-eyes-hq.png","./assets/reference/market-owl-hq.png","./sharp-icons.js?v=66","./bank-detail.js?v=66","./bank-detail.css?v=66","./assets/reference/transfer-pattern.svg","./icon-catalog.js?v=66","./mobile-stability.js?v=66","./mobile-stability.css?v=66","./pull-refresh.js?v=66","./hosted-storage.js?v=66","./card-stable.js?v=66","./card-stable.css?v=66","./profile-pwa.js?v=66","./profile-pwa.css?v=66","./history-glass.js?v=66","./history-glass.css?v=66","./faithful.css?v=66","./faithful-motion.js?v=66","./faithful-entry.js?v=66","./receipt-links.js?v=66","./native-reference.js?v=66","./native-reference.css?v=66","./reference-fidelity.js?v=66","./reference-fidelity.css?v=66","./continuity.js?v=66","./continuity.css?v=66","./motion.js?v=66","./motion.css?v=66","./recording.js?v=66","./recording.css?v=66","./interactions.js?v=66","./interactions.css?v=66","./surfaces.js?v=66","./surfaces.css?v=66","./refinement.css?v=66","./refinement.js?v=66","./reference.css?v=66","./experience.js?v=66","./style.css?v=66","./app.js?v=66","./manifest.json","./icon.svg","./icon.png","./pwa-runtime.js?v=66","./pwa-runtime.css?v=66","./admin-manifest.json"];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting()))});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('mono-mock-')&&key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',event=>{const request=event.request,url=new URL(request.url);if(request.method!=='GET'||url.origin!==self.location.origin||url.pathname.startsWith('/api/'))return;
 if(request.mode==='navigate'){event.respondWith(fetch(new Request(request,{cache:'no-store'})).catch(()=>new Response('<!doctype html><meta name="viewport" content="width=device-width"><style>html{background:#161616;color:white;font:18px system-ui;padding:24px}</style>Потрібне з’єднання з інтернетом. Відкрийте застосунок повторно після підключення.',{headers:{'Content-Type':'text/html; charset=utf-8'}})));return}
 event.respondWith(fetch(request).then(response=>{if(response.ok&&url.pathname.startsWith('/assets/')){const copy=response.clone();event.waitUntil(caches.open(CACHE).then(cache=>cache.put(request,copy)))}return response}).catch(()=>caches.match(request).then(cached=>cached||Response.error())))
});
